function frameSource(asset: PaletteAsset, frame: number): { x: number; y: number } { const column = frame % asset.columns, row = Math.floor(frame / asset.columns); return { x: asset.margin + column * (asset.tileSize + asset.spacing), y: asset.margin + row * (asset.tileSize + asset.spacing) }; }
function drawAsset(context: CanvasRenderingContext2D, assetId: string, frameNumber: number, dx: number, dy: number, size: number): void { const asset = catalogAsset(assetId), image = images.get(assetId); if (!asset || !image?.complete || image.naturalWidth === 0 || frameNumber < 0 || frameNumber >= asset.frameCount) { context.fillStyle = "#a94055"; context.fillRect(dx, dy, size, size); context.strokeStyle = "#ffd5db"; context.beginPath(); context.moveTo(dx, dy); context.lineTo(dx + size, dy + size); context.moveTo(dx + size, dy); context.lineTo(dx, dy + size); context.stroke(); return; } const source = frameSource(asset, frameNumber); context.drawImage(image, source.x, source.y, asset.tileSize, asset.tileSize, dx, dy, size, size); }
