async function loadAssetCatalog(preferredAssetId?: string): Promise<void> {
  try {
    const response = await fetch(`/assets/map-tiles/generated/catalog.json?editor=${Date.now()}`, { cache: "no-store", headers: { Accept: "application/json" } });
    if (!response.ok) throw new Error("asset catalog endpoint unavailable");
    const incoming = await response.json() as { assets?: PaletteAsset[] };
    if (!Array.isArray(incoming.assets)) throw new Error("asset catalog is invalid");
    assets = incoming.assets.map((asset) => ({ ...asset, mapKinds: [...asset.mapKinds] }));
    assetById = new Map(assets.map((asset) => [asset.id, asset]));
    for (const id of [...images.keys()]) if (!assetById.has(id)) images.delete(id);
    for (const asset of assets) {
      const current = images.get(asset.id);
      if (current?.src.endsWith(asset.path)) continue;
      const image = new Image(); image.onload = () => render(); image.src = asset.path; images.set(asset.id, image);
    }
    const requested = preferredAssetId ?? sessionStorage.getItem(selectedAssetStorageKey) ?? selectedAssetId;
    if (requested && assetById.has(requested)) { selectedAssetId = requested; sessionStorage.setItem(selectedAssetStorageKey, requested); }
    revealSelectedAsset = true;
  } catch (error) {
    status.textContent = `素材一覧の再読込エラー: ${error instanceof Error ? error.message : "不明"}`;
  }
}
