applyFloorButton.onclick = async () => {
  if (!active || active.kind !== "dungeon") return;
  try {
    const requestedFloor = Number(mapFloor.value);
    const updates = planDungeonFloorMove(maps, active.id, requestedFloor);
    if (!updates.length) { status.textContent = `地下${active.floor}階のままです。`; return; }
    applyDungeonFloorUpdates(maps, updates);
    applyDungeonFloorUpdates([active], updates);
    for (const update of updates) {
      const map = maps.find((candidate) => candidate.id === update.id);
      if (!map) continue;
      touch(map);
      await repository.save(map);
    }
    touch(active);
    mapFloor.value = String(active.floor);
    status.textContent = `地下${active.floor}階へ移動しました。間の階層は自動的に並べ替えました。`;
    render();
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : "階層を変更できません。";
    mapFloor.value = String(active.floor);
  }
};
